:root{
  --paper:#f8f4ea;--paper2:#fffdf8;--tea:#5e4324;--ink:#342b22;--muted:#766a5b;
  --jade:#496f60;--jade2:#7e9a8b;--gold:#a8762d;--red:#a74e40;
  --sans:"Microsoft YaHei","PingFang SC","Noto Sans CJK SC",sans-serif;
  --kai:"KaiTi","STKaiti","Kaiti SC","FangSong",serif;
  --scene-lotus:url("data:image/webp;base64,");--scene-water:url("data:image/webp;base64,");
  --scene-crane:url("data:image/webp;base64,");--scene-mountain:url("data:image/webp;base64,");--scene-vine-art:url("data:image/webp;base64,");
  --art-hero:url("data:image/webp;base64,");--art-bamboo:url("data:image/webp;base64,");--art-study:url("data:image/webp;base64,");
  --art-autumn:url("data:image/webp;base64,");--art-plum:url("data:image/webp;base64,");--art-cloud:url("data:image/webp;base64,");
}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--paper);color:var(--ink);font-family:var(--sans)}
button{font:inherit;color:inherit}
button:focus-visible{outline:2px solid rgba(168,118,45,.46);outline-offset:3px}
body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:0;background:radial-gradient(65vw 50vh at 83% 4%,rgba(91,131,112,.105),transparent 72%),radial-gradient(45vw 55vh at 2% 100%,rgba(179,128,57,.08),transparent 70%),linear-gradient(140deg,#fffdf8,#f7f2e7 62%,#f4eee1)}
body::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:0;opacity:.16;background-image:repeating-linear-gradient(0deg,transparent 0 3px,rgba(74,55,35,.018) 4px),radial-gradient(circle at 30% 40%,rgba(67,52,35,.035) 0 1px,transparent 1.3px);background-size:auto,18px 18px}
#app{position:fixed;inset:0;z-index:1;overflow:hidden}

/* persistent art depth */
.depth-art{position:absolute;inset:0;pointer-events:none;z-index:0;overflow:hidden}
.depth-art .far{position:absolute;right:-4%;top:-8%;width:50%;height:42%;background:var(--art-hero) center/cover no-repeat;opacity:.105;mask-image:linear-gradient(105deg,transparent,#000 32%,#000 74%,transparent)}
.depth-art .mid{position:absolute;left:-9%;bottom:-18%;width:42%;height:57%;background:var(--scene-water) center/cover no-repeat;opacity:.07;mask-image:radial-gradient(ellipse,#000 0 48%,transparent 75%)}
.depth-art .near{position:absolute;right:0;bottom:6%;width:18%;height:46%;background:var(--art-plum) center/contain no-repeat;opacity:.065}

.topbar{position:absolute;left:4.7%;right:4.5%;top:3.2%;height:56px;z-index:30;display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;gap:12px;color:#6a4820}
.brand-seal{width:48px;height:48px;border:1px solid rgba(168,118,45,.30);border-radius:50%;display:grid;place-items:center;font:700 24px/1 var(--kai);background:rgba(255,253,247,.56)}
.brand-copy b{display:block;font:700 20px/1 var(--kai);letter-spacing:.14em} .brand-copy span{display:block;margin-top:5px;font-size:9px;color:#96764f;letter-spacing:.20em}
.mode-switch{display:flex;gap:5px;padding:4px;border-bottom:1px solid rgba(112,87,51,.17)}
.mode-switch button{border:0;background:transparent;padding:9px 16px;border-radius:999px;cursor:pointer;color:#796c5c;font:700 13px/1 var(--kai);letter-spacing:.05em}
.mode-switch button.active{color:#65451f;background:rgba(255,252,244,.83);box-shadow:inset 0 0 0 1px rgba(168,118,45,.15),0 7px 20px rgba(77,57,35,.06)}
.mode-toast{position:absolute;right:5%;top:10%;z-index:50;padding:10px 14px;border-left:2px solid rgba(73,111,96,.42);background:rgba(255,253,247,.88);font-size:11px;color:#675a4c;opacity:0;transform:translateY(-6px);transition:.22s;pointer-events:none} .mode-toast.show{opacity:1;transform:none}

/* UNIFIED PAGE GRID: same geometry on all four pages */
.workspace{position:absolute;inset:0;z-index:5;opacity:0;visibility:hidden;pointer-events:none}
.workspace.active{opacity:1;visibility:visible;pointer-events:auto}
.page-grid{position:absolute;left:4.6%;right:4.6%;top:11.5%;bottom:14.5%;display:grid;grid-template-columns:31.5% 1fr;gap:4.2%;min-height:0}
.left-column{display:grid;grid-template-rows:35% 1fr;gap:6%;min-width:0;min-height:0}
.identity-island{position:relative;padding:8.5% 7% 7% 10%;border-left:3px solid rgba(168,118,45,.46);border-bottom:1px solid rgba(112,87,51,.13);background:linear-gradient(130deg,rgba(255,253,247,.78),rgba(255,251,242,.26));box-shadow:0 18px 55px rgba(75,56,35,.055);overflow:hidden;clip-path:polygon(0 0,94% 0,100% 20%,90% 100%,0 100%)}
.identity-island::after{content:"";position:absolute;right:-3%;top:-3%;width:36%;height:105%;background:var(--art-bamboo) center/cover no-repeat;opacity:.13;mask-image:linear-gradient(to left,#000,transparent 88%)}
.identity-kicker{position:relative;z-index:2;font-size:10px;letter-spacing:.18em;color:#a06f2b;font-weight:850}
.identity-island h1{position:relative;z-index:2;margin:6% 0 4%;font:700 clamp(25px,3.2vw,43px)/1.12 var(--kai);color:#5f4320;letter-spacing:.02em}
.identity-island p{position:relative;z-index:2;margin:0;max-width:93%;font-size:clamp(11px,1.25vw,15px);line-height:1.8;color:#6f6558}
.identity-meta{position:relative;z-index:2;margin-top:5%;font-size:10px;color:#907f6d;letter-spacing:.03em}
.identity-grow{position:absolute;left:2.2%;top:7%;bottom:7%;width:58px;pointer-events:none;z-index:1}
.identity-grow path{fill:none;stroke-linecap:round;stroke-dasharray:520;stroke-dashoffset:0} .identity-grow .main{stroke:rgba(168,118,45,.42);stroke-width:1.8} .identity-grow .side{stroke:rgba(73,111,96,.36);stroke-width:1.15}
.identity-grow ellipse{fill:rgba(73,111,96,.26);opacity:1;transform-box:fill-box;transform-origin:center;transform:scale(1)}

.left-story{position:relative;min-height:0;padding:2% 2% 0 5%}
.story-head{height:34px;display:flex;align-items:end;justify-content:space-between;margin-bottom:3%}
.story-head b{font:700 clamp(17px,1.8vw,23px)/1.1 var(--kai);color:#674920} .story-head span{font-size:9px;letter-spacing:.18em;color:#a17d4d}
.story-canvas{position:relative;height:calc(100% - 40px);min-height:0}
.story-canvas svg.flow-line{position:absolute;inset:1% 0 0 0;width:100%;height:94%;overflow:visible}
.story-canvas svg.flow-line path{fill:none;stroke:rgba(73,111,96,.48);stroke-width:2;stroke-linecap:round;stroke-dasharray:800;stroke-dashoffset:0}
.story-node{position:absolute;width:min(80%,245px);padding:10px 15px 11px 17px;border:0;background:transparent;text-align:left;cursor:pointer;opacity:1;transform:none}
.story-node::before{content:"";position:absolute;inset:0;border-radius:50% 45% 51% 44%;background:rgba(255,253,247,.72);border:1px solid rgba(73,111,96,.15);box-shadow:0 11px 27px rgba(71,54,36,.055);z-index:-1}
.story-node .t{font-size:10px;color:#a17d4d;font-weight:800} .story-node .n{display:block;margin-top:3px;font:700 clamp(13px,1.35vw,17px)/1.2 var(--kai)} .story-node .s{display:block;margin-top:3px;font-size:10px;line-height:1.4;color:#837666}
.story-node.pending::after{content:"";position:absolute;right:11px;top:11px;width:8px;height:8px;border-radius:50%;background:#a74e40;animation:nodePulse 1.65s infinite}
.story-node.done{filter:saturate(.72)}
.story-node.n1{left:0;top:2%} .story-node.n2{right:1%;top:33%} .story-node.n3{left:7%;top:67%}

.right-stage{position:relative;min-width:0;min-height:0;border-top:1px solid rgba(112,87,51,.09)}
.stage-copy{position:absolute;left:3%;top:4%;z-index:7;max-width:53%;min-width:260px}
.stage-kicker{font-size:10px;letter-spacing:.20em;color:#98713e;font-weight:850}
.stage-copy h2{margin:5px 0 8px;font:700 clamp(31px,4.1vw,58px)/1.08 var(--kai);color:#59401f;letter-spacing:.02em}
.stage-copy p{margin:0;max-width:520px;color:#6e6458;font-size:clamp(11px,1.12vw,14px);line-height:1.75}
.stage-art{position:absolute;right:-2%;top:4%;width:51%;height:75%;opacity:.18;pointer-events:none;background-position:center;background-repeat:no-repeat;background-size:contain;mask-image:linear-gradient(95deg,transparent,#000 30%,#000 78%,transparent 100%);animation:artFloat 8s ease-in-out infinite alternate}
.stage-accent{position:absolute;right:1%;bottom:0;width:30%;height:33%;opacity:.075;background:var(--art-cloud) center/contain no-repeat;pointer-events:none}

/* TODAY stage */
.quick-row{position:absolute;left:3%;top:28%;width:51%;display:flex;gap:8px;flex-wrap:wrap;z-index:8}
.quick-chip{border:1px solid rgba(73,111,96,.16);background:rgba(255,253,247,.50);padding:8px 12px;border-radius:999px;cursor:pointer;color:#66594b;font-size:10px;transition:.2s} .quick-chip:hover{transform:translateY(-2px);background:rgba(255,253,247,.92)}
.voice-zone{position:absolute;right:5%;top:17%;width:41%;height:48%;display:grid;place-items:center;z-index:7}
.voice-orbit{position:absolute;inset:4%;border:1px solid rgba(73,111,96,.16);border-radius:50%;animation:orbit 14s linear infinite} .voice-orbit::before,.voice-orbit::after{content:"";position:absolute;inset:13%;border:1px solid rgba(168,118,45,.12);border-radius:50%} .voice-orbit::after{inset:28%;border-color:rgba(73,111,96,.13)}
.voice-orb{position:relative;width:clamp(105px,12vw,148px);height:clamp(105px,12vw,148px);border:0;border-radius:50%;cursor:pointer;color:#fff;z-index:3;background:radial-gradient(circle at 33% 28%,rgba(255,255,255,.32),transparent 20%),radial-gradient(circle at 50% 60%,#5d8273,#315e52 68%,#24483f);box-shadow:0 20px 50px rgba(49,94,82,.22),0 0 0 11px rgba(49,94,82,.06),0 0 0 23px rgba(49,94,82,.03);animation:voiceBreath 2.25s ease-in-out infinite} .voice-orb svg{width:37%;height:37%;stroke:currentColor}
.voice-caption{position:absolute;bottom:-4%;text-align:center} .voice-caption b{display:block;font:700 clamp(15px,1.6vw,19px)/1.3 var(--kai);color:#5f5244} .voice-caption span{font-size:9px;color:#8e806f}
.next-card{position:absolute;left:3%;bottom:4%;width:48%;padding:17px 22px 17px 24px;border-left:3px solid rgba(167,78,64,.48);border-bottom:1px solid rgba(112,87,51,.14);background:linear-gradient(125deg,rgba(255,253,247,.83),rgba(255,250,240,.30));box-shadow:0 16px 40px rgba(72,55,35,.055);clip-path:polygon(0 0,94% 0,100% 28%,89% 100%,0 100%)}
.next-card .label{font-size:9px;letter-spacing:.18em;color:#a44f41;font-weight:900} .next-card strong{display:block;margin-top:5px;font:700 clamp(17px,2vw,24px)/1.25 var(--kai);color:#57401f} .next-card .meta{display:flex;gap:14px;flex-wrap:wrap;margin-top:7px;font-size:10px;color:#7e7061}
.keyboard-entry{position:absolute;right:1.5%;bottom:4%;border:0;background:transparent;border-bottom:1px solid rgba(168,118,45,.25);padding:8px 10px;cursor:pointer;font:700 12px var(--kai);color:#6a5b49}

/* RECORDS: same grid, main becomes a river */
.record-river{position:absolute;left:3%;right:2%;top:25%;bottom:4%;z-index:5}
.record-river svg{position:absolute;inset:0;width:100%;height:100%} .record-river path{fill:none;stroke:rgba(73,111,96,.42);stroke-width:2;stroke-linecap:round;stroke-dasharray:1200;stroke-dashoffset:0}
.record-event{position:absolute;width:31%;min-width:160px;padding:12px 14px;border:1px solid rgba(73,111,96,.14);background:rgba(255,253,247,.73);border-radius:48% 44% 46% 42%;box-shadow:0 12px 30px rgba(70,54,36,.06);cursor:pointer;text-align:left;opacity:1;transform:none} .record-event b{font:700 clamp(13px,1.4vw,16px)/1.2 var(--kai);color:#5b4323} .record-event small{display:block;margin-top:5px;font-size:9px;line-height:1.5;color:#857766}
.record-event.e1{left:1%;top:7%} .record-event.e2{left:35%;top:41%} .record-event.e3{right:1%;top:10%} .record-event.e4{right:11%;bottom:3%}
.record-tools{position:absolute;left:3%;bottom:1%;display:flex;gap:12px;z-index:9}
.ghost-btn{border:0;background:transparent;padding:8px 9px;border-bottom:1px solid rgba(168,118,45,.27);cursor:pointer;color:#65584a;font:700 11px var(--kai)}

/* FAMILY: branch composition */
.family-tree{position:absolute;left:3%;right:2%;top:24%;bottom:2%;z-index:5}
.family-tree svg{position:absolute;inset:0;width:100%;height:100%} .family-tree path{fill:none;stroke:rgba(73,111,96,.46);stroke-width:2.1;stroke-linecap:round;stroke-dasharray:900;stroke-dashoffset:0}
.family-core{position:absolute;left:42%;top:30%;width:clamp(135px,15vw,180px);aspect-ratio:1;border-radius:50%;display:grid;place-items:center;text-align:center;background:radial-gradient(circle,rgba(255,253,247,.96),rgba(242,235,219,.63) 65%,transparent 70%);box-shadow:0 0 0 1px rgba(168,118,45,.13),0 22px 55px rgba(76,57,34,.07);opacity:1;transform:none} .family-core b{font:700 clamp(19px,2vw,25px)/1.1 var(--kai);color:#60441f} .family-core span{display:block;margin-top:6px;font-size:9px;color:#817363}
.family-branch{position:absolute;width:32%;min-width:220px;padding:22px 26px;border:0;background:rgba(255,253,247,.68);text-align:left;cursor:pointer;border-bottom:1px solid rgba(73,111,96,.16);border-left:2px solid rgba(73,111,96,.30);border-radius:52% 46% 50% 44%;box-shadow:0 12px 32px rgba(70,54,36,.06);opacity:1;transform:none} .family-branch b{display:block;font:700 clamp(20px,1.9vw,28px)/1.2 var(--kai);color:#5d4526;letter-spacing:.04em} .family-branch small{display:block;margin-top:10px;font-size:14px;line-height:1.65;color:#786c5e}
.family-branch.b1{left:1%;top:7%} .family-branch.b2{left:1%;bottom:5%} .family-branch.b3{right:0;top:17%}
.contact-family{margin-top:8px;border:0;background:transparent;color:#a34e41;font-weight:800;cursor:pointer;padding:6px 0;border-bottom:1px solid rgba(168,77,63,.26)}
.family-note{position:absolute;right:0;bottom:2%;width:35%;padding-left:14px;border-left:1px solid rgba(168,118,45,.25);font-size:10px;line-height:1.7;color:#776a59}

/* MINE: editorial two-column settings */
.settings-grid{position:absolute;left:3%;right:3%;top:25%;bottom:3%;display:grid;grid-template-columns:1fr .92fr;gap:7%;z-index:5}
.setting-block{padding:13px 0 14px;border-bottom:1px solid rgba(112,87,51,.12);opacity:1;transform:none} .setting-block h3{margin:0;font:700 clamp(18px,1.9vw,24px)/1.25 var(--kai);color:#5d4526;letter-spacing:.03em} .setting-block p{margin:7px 0 12px;font-size:14px;line-height:1.6;color:#817362}
.segmented{display:flex;gap:7px;flex-wrap:wrap} .seg-btn{min-width:68px;padding:9px 12px;border:1px solid rgba(73,111,96,.15);border-radius:999px;background:rgba(255,253,247,.54);cursor:pointer;font-size:11px;font-weight:700;color:#695d50} .seg-btn.active{background:rgba(73,111,96,.11);color:#315e52;border-color:rgba(49,94,82,.28)}
.service-row,.guard-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid rgba(112,87,51,.11);cursor:pointer;opacity:1;transform:none} .service-row b,.guard-row b{font:700 clamp(12px,1.25vw,15px) var(--kai);color:#5b4323} .service-row span,.guard-row span{font-size:9px;color:#8b7d6c;text-align:right}
.save-pref{margin-top:13px;border:0;background:transparent;color:#315e52;font:700 14px var(--kai);cursor:pointer;padding:8px 0;border-bottom:1px solid rgba(49,94,82,.27)}

/* Dock copied in spirit/layout from family V5.8.4, but elderly labels */
.dock{position:absolute;left:4.7%;right:4.7%;bottom:2.1%;height:9.3%;min-height:66px;z-index:35;display:grid;grid-template-columns:repeat(4,1fr) 1.25fr;align-items:end;gap:7px}
.dock button{position:relative;height:64px;border:0;background:transparent;cursor:pointer;color:#8b7e6e;transition:.2s} .dock button::before{content:"";position:absolute;left:18%;right:18%;top:0;height:1px;background:transparent} .dock button.active{color:#5d4526} .dock button.active::before{background:rgba(168,118,45,.48)} .dock .ico{display:block;margin-bottom:6px;font:700 18px/1 var(--kai)} .dock .txt{display:block;font:700 11px/1 var(--kai);letter-spacing:.08em} .dock .contact{border-left:1px solid rgba(112,87,51,.14);color:#a34e41}

/* Entry choreography — after every cinematic */
.workspace.entering .identity-grow .main{animation:branchGrow 1.35s .08s cubic-bezier(.18,.75,.2,1) both} .workspace.entering .identity-grow .side{animation:branchGrow 1s .42s cubic-bezier(.18,.75,.2,1) both} .workspace.entering .identity-grow ellipse{animation:leafOpen .42s .78s cubic-bezier(.2,.9,.25,1.25) both}
.workspace.entering .identity-kicker{animation:fadeUp .5s .14s both} .workspace.entering .identity-island h1{animation:inkBlock .72s .24s both} .workspace.entering .identity-island p{animation:fadeUp .58s .50s both} .workspace.entering .identity-meta{animation:fadeUp .55s .68s both}
.workspace.entering .story-head{animation:fadeUp .5s .16s both} .workspace.entering .flow-line path{animation:flowGrow 1.35s .35s cubic-bezier(.18,.75,.2,1) both} .workspace.entering .story-node{animation:nodeBloom .48s cubic-bezier(.2,.84,.25,1.18) both} .workspace.entering .story-node.n1{animation-delay:.48s} .workspace.entering .story-node.n2{animation-delay:.78s} .workspace.entering .story-node.n3{animation-delay:1.08s}
.workspace.entering .stage-copy{animation:fadeUp .62s .20s both} .workspace.entering .quick-chip{animation:chipIn .42s both} .workspace.entering .quick-chip:nth-child(1){animation-delay:.45s} .workspace.entering .quick-chip:nth-child(2){animation-delay:.53s} .workspace.entering .quick-chip:nth-child(3){animation-delay:.61s} .workspace.entering .quick-chip:nth-child(4){animation-delay:.69s}
.workspace.entering .voice-zone{animation:voiceEnter .8s .48s cubic-bezier(.18,.8,.2,1) both} .workspace.entering .next-card{animation:cardSweep .68s .70s both}
.workspace.entering .record-river path{animation:recordGrow 1.5s .28s ease both} .workspace.entering .record-event{animation:fadeUp .48s both} .workspace.entering .record-event.e1{animation-delay:.52s} .workspace.entering .record-event.e2{animation-delay:.76s} .workspace.entering .record-event.e3{animation-delay:.98s} .workspace.entering .record-event.e4{animation-delay:1.18s}
.workspace.entering .family-tree path{animation:familyGrow 1.4s .26s both} .workspace.entering .family-core{animation:coreBloom .65s .48s cubic-bezier(.18,.8,.25,1.2) both} .workspace.entering .family-branch{animation:fadeUp .48s both} .workspace.entering .family-branch.b1{animation-delay:.72s} .workspace.entering .family-branch.b2{animation-delay:.90s} .workspace.entering .family-branch.b3{animation-delay:1.08s}
.workspace.entering .setting-block{animation:fadeUp .5s both} .workspace.entering .setting-block:nth-child(1){animation-delay:.42s} .workspace.entering .setting-block:nth-child(2){animation-delay:.64s} .workspace.entering .service-row,.workspace.entering .guard-row{animation:fadeUp .42s both} .workspace.entering .service-row:nth-child(3),.workspace.entering .guard-row:nth-child(1){animation-delay:.62s} .workspace.entering .service-row:nth-child(4),.workspace.entering .guard-row:nth-child(2){animation-delay:.76s} .workspace.entering .service-row:nth-child(5),.workspace.entering .guard-row:nth-child(3){animation-delay:.90s} .workspace.entering .service-row:nth-child(6){animation-delay:1.04s}


/* V2.2 VISIBILITY FAILSAFE
   Final UI state is explicitly visible. This class is applied after each
   entrance choreography so canceled/restarted CSS animations can never
   leave text/cards at opacity:0. */
.workspace.settled .identity-kicker,
.workspace.settled .identity-island h1,
.workspace.settled .identity-island p,
.workspace.settled .identity-meta,
.workspace.settled .story-head,
.workspace.settled .story-node,
.workspace.settled .stage-copy,
.workspace.settled .quick-chip,
.workspace.settled .voice-zone,
.workspace.settled .next-card,
.workspace.settled .record-event,
.workspace.settled .family-core,
.workspace.settled .family-branch,
.workspace.settled .setting-block,
.workspace.settled .service-row,
.workspace.settled .guard-row{
  opacity:1;
  visibility:visible;
  transform:none;
  filter:none;
}
.workspace.settled .identity-grow path,
.workspace.settled .story-canvas svg.flow-line path,
.workspace.settled .record-river path,
.workspace.settled .family-tree path{
  stroke-dashoffset:0;
}
.workspace.settled .identity-grow ellipse{
  opacity:1;
  transform:scale(1);
}

/* subtle art depth responds to pointer */
.right-stage{--drag-x:0px;--drag-y:0px;--drag-x-soft:0px;--drag-y-soft:0px} .right-stage .stage-art{transform:translate3d(var(--drag-x-soft),var(--drag-y-soft),0)} .right-stage .stage-accent{transform:translate3d(var(--drag-x),var(--drag-y),0)}
.right-stage.is-dragging .stage-art,.right-stage.is-dragging .stage-accent{transition:none}

.stage-ripple,.lotus-burst{position:fixed;z-index:1600;pointer-events:none;transform:translate(-50%,-50%);border-radius:50%}
.stage-ripple{width:18px;height:18px;border:1px solid rgba(73,111,96,.48);animation:stageRipple .62s cubic-bezier(.2,.7,.2,1) forwards} .stage-ripple::after{content:"";position:absolute;inset:3px;border:1px solid rgba(168,118,45,.24);border-radius:50%}
.lotus-burst{width:22px;height:22px;border:1px solid rgba(168,118,45,.40);box-shadow:0 0 0 6px rgba(73,111,96,.08);animation:lotusBurst .58s cubic-bezier(.16,.8,.25,1) forwards}

