/* family V5.8.4 cinematic CSS: copied directly */
.page-scene {
  position:fixed;
  inset:0;
  z-index:997;
  pointer-events:none;
  overflow:hidden;
  opacity:0;
}
.page-scene.playing { opacity:1; }

/* shared scene veil: only a hint, never a full opaque cover */
.page-scene::before {
  content:"";
  position:absolute;
  inset:0;
  background:radial-gradient(circle at var(--scene-x,50%) var(--scene-y,50%),
    rgba(255,253,247,.60), rgba(255,250,242,.12) 26%, transparent 58%);
  opacity:0;
}

/* TODAY — water + lotus */
.page-scene[data-scene="today"].playing::before {
  animation:scene-soft-flash .72s ease-out both;
}
.scene-today-lotus,
.scene-care-crane,
.scene-mine-tree,
.scene-todo-leaves {
  position:absolute;
  left:var(--scene-x,50%);
  top:var(--scene-y,50%);
  transform:translate(-50%,-50%);
}
.scene-today-lotus {
  width:118px;
  height:118px;
  background:var(--scene-lotus) center/contain no-repeat;
  opacity:0;
}
.page-scene[data-scene="today"].playing .scene-today-lotus {
  animation:scene-lotus-open .76s cubic-bezier(.16,.82,.18,1) both;
}
.scene-today-ripple,
.scene-care-ring {
  position:absolute;
  left:var(--scene-x,50%);
  top:var(--scene-y,50%);
  width:42px;height:42px;
  border:1px solid rgba(77,117,101,.28);
  border-radius:50%;
  opacity:0;
}
.page-scene[data-scene="today"].playing .scene-today-ripple.r1 {
  animation:scene-ring .78s ease-out both;
}
.page-scene[data-scene="today"].playing .scene-today-ripple.r2 {
  animation:scene-ring .78s .12s ease-out both;
}

/* TODO — golden leaves / task-path sweep */
.scene-todo-track {
  position:absolute;
  left:9vw;
  right:8vw;
  top:50%;
  height:1px;
  background:linear-gradient(90deg,transparent,rgba(170,120,44,.55),rgba(83,103,89,.26),transparent);
  transform:scaleX(.15);
  transform-origin:left center;
  opacity:0;
}
.page-scene[data-scene="todo"].playing .scene-todo-track {
  animation:todo-track .74s cubic-bezier(.2,.8,.2,1) both;
}
.scene-todo-leaves {
  left:15vw;
  top:48%;
  width:72vw;
  height:120px;
  transform:none;
}
.scene-todo-leaves i {
  position:absolute;
  width:19px;height:10px;
  border-radius:90% 10% 90% 10%;
  background:linear-gradient(135deg,#bc8b3b,#6f8b74);
  opacity:0;
  transform:rotate(var(--rot,0deg));
}
.scene-todo-leaves i:nth-child(1){left:2%;top:54%;--rot:18deg}
.scene-todo-leaves i:nth-child(2){left:22%;top:32%;--rot:-22deg}
.scene-todo-leaves i:nth-child(3){left:43%;top:62%;--rot:12deg}
.scene-todo-leaves i:nth-child(4){left:64%;top:28%;--rot:-12deg}
.scene-todo-leaves i:nth-child(5){left:83%;top:48%;--rot:26deg}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i {
  animation:todo-leaf .68s cubic-bezier(.2,.8,.2,1) both;
}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(2){animation-delay:.06s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(3){animation-delay:.12s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(4){animation-delay:.18s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(5){animation-delay:.24s}

/* CARE — crane crossing + jade ring */
.scene-care-crane {
  left:auto;
  right:-120px;
  top:31%;
  width:112px;height:112px;
  transform:none;
  background:var(--scene-crane) center/contain no-repeat;
