/* family V5.8.4 click-crane CSS: copied directly */
.crane-companion {
  position:fixed;
  left:0;
  top:0;
  width:176px;
  height:130px;
  z-index:1400;
  pointer-events:none;
  opacity:0;
  transform:translate3d(0,0,0);
  will-change:transform;
  filter:drop-shadow(0 11px 13px rgba(67,56,43,.10));
}
.crane-companion.is-ready {
  opacity:.95;
  transition:opacity .5s ease;
}
.crane-companion.is-flying {
  filter:
    drop-shadow(0 13px 15px rgba(67,56,43,.11))
    drop-shadow(0 0 8px rgba(91,120,109,.07));
}
.crane-tilt {
  width:100%;
  height:100%;
  transform-origin:54% 54%;
  will-change:transform;
}
.crane-facing {
  width:100%;
  height:100%;
  transform-origin:center;
  will-change:transform;
}
.crane-frame {
  display:block;
  width:100%;
  height:100%;
  object-fit:contain;
  user-select:none;
  -webkit-user-drag:none;
}
.crane-companion:not(.is-flying) .crane-tilt {
  animation:crane-idle-float 5.2s ease-in-out infinite;
}
@keyframes crane-idle-float {
  0%,100% { transform:translateY(0) rotate(0deg); }
  50% { transform:translateY(-2.5px) rotate(.25deg); }
}

/* 首次提示，第一次点击后自动消失 */
.crane-hint {
  position:absolute;
  left:52%;
  top:10%;
  transform:translate(-10%,-100%);
  min-width:132px;
  padding:7px 10px;
  border:1px solid rgba(126,93,52,.12);
  border-radius:22px 28px 20px 26px;
  background:rgba(255,253,247,.80);
  backdrop-filter:blur(9px);
  color:rgba(82,67,51,.68);
  font-family:var(--sans);
  font-size:9px;
  font-weight:700;
  letter-spacing:.05em;
  text-align:center;
  white-space:nowrap;
  opacity:0;
  transition:opacity .35s ease,transform .35s ease;
}
.crane-companion.is-ready:not(.has-flown) .crane-hint {
  opacity:.88;
  transform:translate(-10%,-112%);
  animation:crane-hint-breathe 3.8s ease-in-out infinite;
}
@keyframes crane-hint-breathe {
  0%,100% { box-shadow:0 8px 24px rgba(80,62,41,.035); }
  50% { box-shadow:0 10px 30px rgba(80,62,41,.075); }
}

/* 飞行时留下一点极淡的“气流”，不是路径线 */
.crane-wind {
  position:fixed;
  z-index:1398;
  width:54px;
  height:1px;
  border-radius:99px;
  pointer-events:none;
  opacity:0;
  background:linear-gradient(90deg,transparent,rgba(78,112,98,.24),transparent);
  transform-origin:center;
}
.crane-wind.play {
  animation:crane-wind-fade .62s ease-out both;
}
@keyframes crane-wind-fade {
  0% { opacity:0; transform:scaleX(.2); }
  28% { opacity:.58; }
  100% { opacity:0; transform:scaleX(1.5); }
}

@media(prefers-reduced-motion:reduce) {
  .crane-companion:not(.is-flying) .crane-tilt { animation:none !important; }
  .crane-hint { animation:none !important; }
}


/* V5.7.1 · 直线飞行 + 27帧平滑化 */
.crane-companion.is-flying .crane-frame{
  image-rendering:auto;
}
.crane-wind{
  opacity:.75;
}


/* V5.7.2 · Ultra frame animation */
.crane-frame{
  image-rendering:auto;
  transform:translateZ(0);
  backface-visibility:hidden;
}
.crane-companion.is-flying .crane-frame{
  will-change:contents;
}


/* V5.7.3 · Integer-cycle flight solver */
.crane-companion[data-cycles]{
  --flight-cycle-valid:1;
}


/* Ensure the demo keeps motion even if OS requests reduced motion. */
@media(prefers-reduced-motion:reduce){.page-scene,.vine-field{display:block!important}.workspace.entering *{animation-play-state:running!important}}


/* Elder refined post-entry vine: overrides the copied family defaults, keeps it quiet. */
.vine-field{position:fixed;inset:0;z-index:2;pointer-events:none;overflow:hidden;opacity:.55!important}
.vine-field svg{position:absolute!important;right:-3%!important;bottom:-5%!important;width:min(34vw,560px)!important;height:min(70vh,720px)!important;overflow:visible}
.vine-field .vine-main,.vine-field .vine-side{fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1500;stroke-dashoffset:1500}
.vine-field .vine-main{stroke:rgba(73,111,96,.18)!important;stroke-width:1.7!important}
.vine-field .vine-side{stroke:rgba(168,118,45,.12)!important;stroke-width:1.05!important}
.vine-field .vine-leaf{fill:rgba(73,111,96,.12)!important;opacity:0;transform-box:fill-box;transform-origin:center;transform:scale(.18)}
.vine-field.grow .vine-main{animation:vineGrow 2.35s .1s both!important}
.vine-field.grow .vine-side{animation:vineGrow 1.8s .55s both!important}
.vine-field.grow .vine-leaf{animation:leafOpen .42s 1.2s both!important}
@media(prefers-reduced-motion:reduce){.page-scene,.scene-copy,.vine-field{display:block!important}.scene-copy{visibility:visible!important}.workspace.entering *{animation-play-state:running!important}}

