/* ==========================================================
   V2.4 · 老人端大字 + 家人端有机气泡重构
   核心：文字必须真的“嵌在”椭圆里，而不是漂浮在轮廓上。
   ========================================================== */
:root{--elder-body:clamp(15px,1.22vw,18px);--elder-small:clamp(12px,1.0vw,14px);--elder-label:clamp(13px,1.05vw,15px)}

/* 顶部品牌减字 */
.brand-copy b{font-size:24px;letter-spacing:.12em}
.brand-copy span{display:none}
.mode-switch button{font-size:15px;padding:10px 20px}

/* 左上身份区：删掉英文后，把真正需要的信息放大 */
.identity-kicker{font-size:14px;letter-spacing:.12em;color:#9a6825}
.identity-island h1{font-size:clamp(31px,3.15vw,46px);line-height:1.12;margin:5% 0 4%}
.identity-island p{font-size:var(--elder-body);line-height:1.72;max-width:88%;font-weight:560}
.identity-meta{margin-top:5%;font-size:13px;color:#897967}
.story-head{height:42px;margin-bottom:2%}
.story-head b{font-size:clamp(23px,2.05vw,29px);letter-spacing:.05em}
.story-head span{display:none}

/* ===== 家人端同款“有机气泡” ===== */
.story-canvas{height:calc(100% - 46px);overflow:visible}
.story-canvas svg.flow-line{z-index:1;inset:1% 2% 0 2%;width:96%;height:96%}
.story-canvas svg.flow-line path{
  stroke-width:1.8;
  stroke:rgba(73,111,96,.52);
  filter:drop-shadow(0 1px 0 rgba(255,255,255,.7));
}
.story-node{
  z-index:3;
  width:min(92%,315px);
  min-height:94px;
  padding:14px 24px 14px 20px;
  display:grid;
  grid-template-columns:66px minmax(0,1fr);
  grid-template-rows:auto auto;
  column-gap:10px;
  align-content:center;
  align-items:center;
  border:1px solid rgba(111,82,48,.14);
  border-radius:52% 48% 46% 54% / 58% 45% 55% 42%;
  background:
    radial-gradient(circle at 18% 18%,rgba(255,255,255,.82),transparent 34%),
    linear-gradient(135deg,rgba(255,252,245,.94),rgba(243,232,213,.60));
  box-shadow:0 14px 32px rgba(82,61,39,.07),inset 0 0 30px rgba(255,255,255,.25);
  text-align:left;
  overflow:hidden;
}
.story-node::before{display:none}
.story-node:nth-of-type(2){border-radius:46% 54% 54% 46% / 48% 56% 44% 52%}
.story-node:nth-of-type(3){border-radius:55% 45% 49% 51% / 43% 58% 42% 57%}
.story-node .t{
  grid-column:1;grid-row:1 / span 2;
  align-self:center;
  font-family:var(--sans);font-size:14px;font-weight:850;color:#98713e;
  white-space:normal;line-height:1.3;
}
.story-node .n{
  grid-column:2;grid-row:1;
  margin:0;
  font:700 clamp(18px,1.6vw,22px)/1.18 var(--kai);
  color:#3f3429;white-space:normal
}
.story-node .s{
  grid-column:2;grid-row:2;
  margin:5px 0 0;
  font-size:clamp(12px,1.0vw,14px);
  line-height:1.35;color:#776b5d;font-weight:580;
  white-space:normal
}
.story-node.done{opacity:.78;filter:saturate(.68)}
.story-node.pending{
  border-color:rgba(168,118,45,.30);
  background:
    radial-gradient(circle at 20% 16%,rgba(255,255,255,.93),transparent 31%),
    linear-gradient(135deg,rgba(255,250,239,.98),rgba(226,236,227,.72));
  box-shadow:0 16px 34px rgba(92,66,38,.08),0 0 0 1px rgba(168,118,45,.035) inset
}
.story-node.pending::after{right:18px;top:50%;transform:translateY(-50%);width:10px;height:10px}
.story-node.n1{left:0;top:1%}
.story-node.n2{right:-1%;top:34%}
.story-node.n3{left:8%;top:68%}

/* 主舞台：正文和功能文字做老人可读字号 */
.stage-kicker{font-size:14px;letter-spacing:.12em}
.stage-copy{max-width:56%}
.stage-copy h2{font-size:clamp(38px,4.3vw,62px);margin:6px 0 12px}
.stage-copy p{font-size:var(--elder-body);line-height:1.72;max-width:500px;font-weight:560}
.quick-row{top:30%;gap:10px;width:54%}
.quick-chip{font-size:14px;padding:11px 16px;font-weight:650}
.next-card{padding:20px 25px 20px 27px}
.next-card .label{font-size:13px;letter-spacing:.10em}
.next-card strong{font-size:clamp(22px,2.2vw,29px)}
.next-card .meta{font-size:13px;gap:18px}
.keyboard-entry{font-size:15px;padding:10px 13px}

/* 用户给的新国风麦克风：保留整颗图做呼吸，不再画旧的绿色圆球 */
.voice-zone{right:2%;top:12%;width:46%;height:59%}
.voice-orbit{inset:8%;border-color:rgba(168,118,45,.18);animation-duration:15s}
.voice-orbit::before{inset:11%;border-color:rgba(73,111,96,.15)}
.voice-orbit::after{inset:24%;border-color:rgba(168,118,45,.12)}
.voice-orb{
  width:clamp(210px,21vw,300px);
  height:clamp(210px,21vw,300px);
  padding:0;border:0;border-radius:50%;
  background:transparent;
  box-shadow:none;
  animation:elderMicBreath 2.35s ease-in-out infinite;
  overflow:visible;
}
.voice-art-mic{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 20px 30px rgba(84,61,34,.13))}
.voice-caption{bottom:-2%}
.voice-caption b{font-size:clamp(19px,1.7vw,23px)}
.voice-caption span{font-size:13px}
@keyframes elderMicBreath{
  0%,100%{transform:scale(1);filter:drop-shadow(0 0 0 rgba(168,118,45,0))}
  48%{transform:scale(1.045);filter:drop-shadow(0 0 18px rgba(168,118,45,.22))}
}

/* 记录页：卡片也采用同一套有机椭圆，不再是小字漂浮矩形 */
.record-river{top:27%}
.record-event{
  width:32%;min-width:205px;min-height:104px;
  padding:18px 22px;
  display:flex;flex-direction:column;justify-content:center;
  border-radius:52% 48% 46% 54% / 58% 45% 55% 42%;
  background:
    radial-gradient(circle at 18% 18%,rgba(255,255,255,.84),transparent 34%),
    linear-gradient(135deg,rgba(255,252,245,.94),rgba(242,233,216,.56));
  z-index:3
}
.record-event b{font-size:clamp(18px,1.6vw,22px);line-height:1.2}
.record-event small{font-size:13px;line-height:1.48;margin-top:7px}
.record-tools{bottom:0;gap:18px}
.ghost-btn{font-size:14px;padding:10px 11px}

/* 家人页：分支同样变成大号有机节点，让文字真正落在图形内部 */
.family-tree svg{z-index:1}
.family-core{z-index:4;width:clamp(180px,17vw,220px)}
.family-core b{font-size:clamp(25px,2.35vw,33px)}
.family-core span{font-size:13px;margin-top:9px}
.contact-family{font-size:18px;margin-top:12px;padding:9px 0}
.family-branch{
  z-index:3;width:31%;min-width:230px;min-height:118px;
  padding:19px 24px;
  display:flex;flex-direction:column;justify-content:center;
  border:1px solid rgba(111,82,48,.13);
  border-radius:52% 48% 46% 54% / 58% 45% 55% 42%;
  background:
    radial-gradient(circle at 18% 18%,rgba(255,255,255,.84),transparent 34%),
    linear-gradient(135deg,rgba(255,252,245,.92),rgba(243,232,213,.55));
  box-shadow:0 14px 34px rgba(82,61,39,.065),inset 0 0 28px rgba(255,255,255,.20)
}
.family-branch.b1{left:0;top:4%}
.family-branch.b2{left:0;bottom:3%}
.family-branch.b3{right:0;top:12%}
.family-branch b{font-size:clamp(20px,1.75vw,24px);line-height:1.18}
.family-branch small{font-size:13px;line-height:1.45;margin-top:8px}
.family-note{font-size:14px;line-height:1.65;width:36%;bottom:1%;padding-left:18px}
.family-note b{font-size:16px}

/* 我的：删掉“说明性小字感”，让设置项本身成为主角 */
.settings-grid{top:27%;gap:6%}
.setting-block{padding:17px 0 18px}
.setting-block h3{font-size:clamp(21px,1.85vw,25px)}
.setting-block p{font-size:13px;line-height:1.5;margin:6px 0 13px}
.seg-btn{min-width:82px;font-size:15px;padding:11px 15px}
.service-row,.guard-row{padding:15px 0}
.service-row b,.guard-row b{font-size:clamp(17px,1.45vw,20px)}
.service-row span,.guard-row span{font-size:13px}
.save-pref{font-size:17px;padding:11px 0;margin-top:16px}

/* 底栏老人端需要更明显 */
.dock{height:10.5%;bottom:1.6%}
.dock button{height:72px}
.dock .ico{font-size:22px;margin-bottom:7px}
.dock .txt{font-size:15px;letter-spacing:.05em}
.dock .contact .txt{font-size:16px}

/* 视觉层级：线必须在气泡下，气泡文字永远在最前 */
.story-canvas .flow-line,.record-river svg,.family-tree svg{pointer-events:none}
.story-node,.record-event,.family-branch,.family-core{isolation:isolate}
.story-node > *, .record-event > *, .family-branch > *, .family-core > *{position:relative;z-index:2}

/* 小屏自适应：宁可减少附加说明，也不要缩小核心字 */
@media(max-width:1100px){
  .page-grid{grid-template-columns:34% 1fr;gap:3%}
  .story-node{min-height:86px;grid-template-columns:56px 1fr;padding:12px 18px}
  .story-node .n{font-size:18px}
  .story-node .s{font-size:12px}
  .stage-copy h2{font-size:clamp(34px,4.8vw,50px)}
  .stage-copy p{font-size:15px}
  .voice-orb{width:220px;height:220px}
  .family-branch{min-width:195px;padding:16px 18px}
  .family-branch small{font-size:12px}
}
@media(max-height:760px){
  .identity-island p{font-size:14px;line-height:1.55}
  .identity-meta{font-size:12px}
  .story-node{min-height:78px;padding-top:10px;padding-bottom:10px}
  .story-node .n{font-size:17px}
  .story-node .s{font-size:11px}
  .family-branch{min-height:96px}
  .voice-orb{width:200px;height:200px}
  .voice-caption b{font-size:18px}
}


