}
.settings-grid{
  overflow:hidden;
}

/* V2.4.3 title de-dup + spacing cleanup */
.family-scene .stage-head,
.mine-scene .stage-head{
  max-width:48%;
}
.family-tree{
  top:27vh;
}
.settings-grid{
  top:25vh;
}
.family-branch{
  z-index:3;
}
.family-branch b,
.family-branch small,
.setting-block h3,
.setting-block p{
  position:relative;
  z-index:2;
}
.stage-head h2,
.stage-head p{
  position:relative;
  z-index:4;
}
.stage-head h2{
  margin-bottom:12px;
}


/* =========================================================
   V2.4.4 · 背景画卷增强动态
   不再只是统一上下浮动：远景 / 中景 / 近景 / 页面主画卷
   使用不同方向、速度、幅度、缩放和轻微旋转，形成明显景深。
   使用 translate / scale / rotate 独立属性，不破坏原有 stage 拖动 transform。
   ========================================================= */

.depth-art .far{
  opacity:.15;
  transform-origin:72% 36%;
  will-change:translate,scale,rotate,opacity,filter;
  animation:elderFarPainting 13.5s cubic-bezier(.45,.05,.28,.98) infinite alternate;
}
.depth-art .mid{
  opacity:.105;
  transform-origin:34% 73%;
  will-change:translate,scale,rotate,opacity,filter;
  animation:elderMidPainting 10.8s cubic-bezier(.42,.1,.26,.98) infinite alternate;
}
.depth-art .near{
  opacity:.105;
  transform-origin:68% 80%;
  will-change:translate,scale,rotate,opacity,filter;
  animation:elderNearPainting 8.8s cubic-bezier(.44,.06,.25,.98) infinite alternate;
}

/* 主舞台画卷整体更明显 */
.right-stage .stage-art{
  opacity:.25;
  transform-origin:61% 50%;
  will-change:translate,scale,rotate,opacity,filter,transform;
}
.right-stage .stage-accent{
  opacity:.115;
  transform-origin:68% 70%;
  will-change:translate,scale,rotate,opacity,transform;
  animation:elderCloudDrift 7.7s ease-in-out infinite alternate;
}

/* 每页主画卷故意采用不同节奏，避免“四页都是同一张图在飘” */
.workspace[data-workspace="today"] .stage-art{
  animation:elderMountainPainting 9.4s ease-in-out infinite alternate;
}
.workspace[data-workspace="records"] .stage-art{
  animation:elderStudyPainting 11.2s cubic-bezier(.4,.05,.3,1) infinite alternate;
}
.workspace[data-workspace="family"] .stage-art{
  animation:elderAutumnPainting 10.1s ease-in-out infinite alternate;
}
.workspace[data-workspace="mine"] .stage-art{
  animation:elderLotusPainting 9s cubic-bezier(.45,.02,.28,.99) infinite alternate;
}

/* 入场时画卷会比文字稍慢一点“浮上来” */
.workspace.entering .stage-art{
  animation-delay:.18s;
}

/* 远景：慢、大范围横向漂移，像远处山景 */
@keyframes elderFarPainting{
  0%{
    translate:14px 10px;
    scale:1.00;
    rotate:-.22deg;
    opacity:.12;
    filter:saturate(.82) contrast(.97);
  }
  42%{
    translate:-16px -5px;
    scale:1.035;
    rotate:.08deg;
    opacity:.17;
    filter:saturate(.94) contrast(1.01);
  }
  100%{
    translate:8px -18px;
    scale:1.06;
    rotate:.38deg;
    opacity:.145;
    filter:saturate(.88) contrast(1.02);
  }
}

/* 中景：方向和远景相反，形成视觉视差 */
@keyframes elderMidPainting{
  0%{
    translate:-12px 12px;
    scale:1.015;
    rotate:.28deg;
    opacity:.075;
    filter:saturate(.86);
  }
  48%{
    translate:19px -10px;
    scale:1.065;
    rotate:-.18deg;
    opacity:.13;
    filter:saturate(.98);
  }
  100%{
    translate:-16px -21px;
    scale:1.04;
    rotate:.12deg;
    opacity:.105;
    filter:saturate(.91);
  }
}

/* 近景梅枝：速度最快、幅度更明显，像真正的前景 */
@keyframes elderNearPainting{
  0%{
    translate:8px 7px;
    scale:1.00;
    rotate:-.65deg;
    opacity:.075;
    filter:saturate(.86);
  }
  45%{
    translate:-14px -11px;
    scale:1.085;
    rotate:.18deg;
    opacity:.135;
    filter:saturate(1.02);
  }
  100%{
    translate:12px -23px;
    scale:1.045;
    rotate:.82deg;
    opacity:.105;
    filter:saturate(.93);
  }
}

/* 今天：山水慢慢靠近，再退回去 */
@keyframes elderMountainPainting{
  0%{
    translate:12px 9px;
    scale:1.00;
    rotate:-.25deg;
    opacity:.205;
    filter:saturate(.82) contrast(.97);
  }
  46%{
    translate:-20px -13px;
    scale:1.07;
    rotate:.13deg;
    opacity:.30;
    filter:saturate(.97) contrast(1.025);
  }
  100%{
    translate:15px -22px;
    scale:1.04;
    rotate:.38deg;
    opacity:.25;
    filter:saturate(.89) contrast(1.01);
  }
}

/* 记录：书斋更稳定，横向游移更明显 */
@keyframes elderStudyPainting{
  0%{
    translate:-9px 12px;
    scale:1.015;
    rotate:.22deg;
    opacity:.20;
    filter:saturate(.84) contrast(.98);
  }
  50%{
    translate:18px -13px;
    scale:1.065;
    rotate:-.22deg;
    opacity:.285;
    filter:saturate(.98) contrast(1.02);
  }
  100%{
    translate:-18px -7px;
    scale:1.04;
    rotate:.34deg;
    opacity:.235;
    filter:saturate(.91) contrast(1.01);
  }
}

/* 家人：秋景略带“呼吸靠近” */
@keyframes elderAutumnPainting{
  0%{
    translate:11px 7px;
    scale:1.00;
    rotate:-.3deg;
    opacity:.19;
    filter:saturate(.87) contrast(.98);
  }
  44%{
    translate:-17px -12px;
    scale:1.055;
    rotate:.12deg;
    opacity:.29;
    filter:saturate(1.045) contrast(1.02);
  }
  100%{
    translate:14px -21px;
    scale:1.08;
    rotate:.43deg;
    opacity:.235;
    filter:saturate(.94) contrast(1.01);
  }
}

/* 我的：荷塘横向缓慢游动，像水面在移动 */
@keyframes elderLotusPainting{
  0%{
    translate:-8px 8px;
    scale:1.00;
    rotate:.18deg;
    opacity:.19;
    filter:saturate(.87) contrast(.98);
  }
  52%{
    translate:20px -15px;
    scale:1.075;
    rotate:-.2deg;
    opacity:.295;
    filter:saturate(1.03) contrast(1.02);
  }
  100%{
    translate:-15px -22px;
    scale:1.045;
    rotate:.34deg;
    opacity:.235;
    filter:saturate(.94) contrast(1.01);
  }
}

/* 云纹前景与画卷不同相位移动 */
@keyframes elderCloudDrift{
  0%{
    translate:-7px 5px;
    scale:1;
    rotate:-.4deg;
    opacity:.075;
  }
  50%{
    translate:13px -10px;
    scale:1.075;
    rotate:.2deg;
    opacity:.14;
  }
  100%{
    translate:-10px -17px;
    scale:1.035;
    rotate:.65deg;
    opacity:.105;
  }
}

/* 鼠标/手指拖动主舞台时，再额外放大景深响应 */
.right-stage.is-dragging .stage-art{
  filter:saturate(1.02) contrast(1.025);
}
.right-stage.is-dragging .stage-accent{
  opacity:.16;
}
